"""English and Arabic copy for the current Persian product catalog.

English follows the live English pages where that text matches the current
catalog, and the Persian page where the live English text is a Google
Translate dump or contradicts the Persian table. Arabic is a translation of
the current Persian catalog. SKU codes are the Persian codes in Latin digits.
"""

_DIGITS = str.maketrans('۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩', '01234567890123456789')

def latin_digits(s):
    return (s or '').translate(_DIGITS)

